import{_ as n,a0 as s,w as d,s as l,ao as p,I as o,x as r,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"在 Kali Linux 的 Wireshark 中過濾數據包 | LCTT x X-CMD","titleTemplate":false,"description":"在 Kali Linux 的 Wireshark 中過濾數據包 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Kali Linux 的 Wireshark 中過濾數據包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Kali Linux 的 Wireshark 中過濾數據包 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170215 Filtering Packets In Wireshark on Kali Linux","title":"在 Kali Linux 的 Wireshark 中過濾數據包","tag":"201708","desc":""},"relativePath":"201708/20170215 Filtering Packets In Wireshark on Kali Linux.md","filePath":"[post].md"}'),h={name:"201708/20170215 Filtering Packets In Wireshark on Kali Linux.md"};function c(k,e,u,x,T,f){const t=s("Link");return d(),l("div",null,[e[13]||(e[13]=p('<h1 id="在-kali-linux-的-wireshark-中過濾數據包" tabindex="-1">在 Kali Linux 的 Wireshark 中過濾數據包 <a class="header-anchor" href="#在-kali-linux-的-wireshark-中過濾數據包" aria-label="Permalink to “在 Kali Linux 的 Wireshark 中過濾數據包”">​</a></h1><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p>數據包過濾可讓你專注於你感興趣的確定數據集。如你所見，Wireshark 默認會抓取_所有_數據包。這可能會妨礙你尋找具體的數據。 Wireshark 提供了兩個功能強大的過濾工​​具，讓你簡單而無痛地獲得精確的數據。</p><p>Wireshark 可以通過兩種方式過濾數據包。它可以通過只收集某些數據包來過濾，或者在抓取數據包後進行過濾。當然，這些可以彼此結合使用，並且它們各自的用處取決於收集的數據和信息的多少。</p><h3 id="布爾表達式和比較運算符" tabindex="-1">布爾表達式和比較運算符 <a class="header-anchor" href="#布爾表達式和比較運算符" aria-label="Permalink to “布爾表達式和比較運算符”">​</a></h3><p>Wireshark 有很多很棒的內置過濾器。當開始輸入任何一個過濾器字段時，你將看到它們會自動補完。這些過濾器大多數對應於用户對數據包的常見分組方式，比如僅過濾 HTTP 請求就是一個很好的例子。</p><p>對於其他的，Wireshark 使用布爾表達式和/或比較運算符。如果你曾經做過任何編程，你應該熟悉布爾表達式。他們是使用 <code>and</code>、<code>or</code>、<code>not</code> 來驗證聲明或表達式的真假。比較運算符要簡單得多，它們只是確定兩件或更多件事情是否彼此相等、大於或小於。</p><h3 id="過濾抓包" tabindex="-1">過濾抓包 <a class="header-anchor" href="#過濾抓包" aria-label="Permalink to “過濾抓包”">​</a></h3><p>在深入自定義抓包過濾器之前，請先查看 Wireshark 已經內置的內容。單擊頂部菜單上的 “Capture” 選項卡，然後點擊 “Options”。可用接口下面是可以編寫抓包過濾器的行。直接移到左邊一個標有 “Capture Filter” 的按鈕上。點擊它，你將看到一個新的對話框，其中包含內置的抓包過濾器列表。看看裏面有些什麼。</p><p><img src="https://linuxconfig.org/images/wireshark-capture-filter.jpg" alt="Wireshark dialog for creating a capture filter"></p><p>在對話框的底部，有一個用於創建並保存抓包過濾器的表單。按左邊的 “New” 按鈕。它將創建一個填充有默認數據的新的抓包過濾器。要保存新的過濾器，只需將實際需要的名稱和表達式替換原來的默認值，然後單擊“Ok”。過濾器將被保存並應用。使用此工具，你可以編寫並保存多個不同的過濾器，以便它們將來可以再次使用。</p><p>抓包有自己的過濾語法。對於比較，它不使用等於號，並使用 <code>&gt;</code> 和 <code>&lt;</code> 來用於大於或小於。對於布爾值來説，它使用 <code>and</code>、<code>or</code> 和 <code>not</code>。</p><p>例如，如果你只想監聽 80 端口的流量，你可以使用這樣的表達式：<code>port 80</code>。如果你只想從特定的 IP 監聽端口 80，你可以使用 <code>port 80 and host 192.168.1.20</code>。如你所見，抓包過濾器有特定的關鍵字。這些關鍵字用於告訴 Wireshark 如何監控數據包以及哪一個數據是要找的。例如，<code>host</code> 用於查看來自 IP 的所有流量。<code>src</code> 用於查看源自該 IP 的流量。與之相反，<code>dst</code> 只監聽目標到這個 IP 的流量。要查看一組 IP 或網絡上的流量，請使用 <code>net</code>。</p><h3 id="過濾結果" tabindex="-1">過濾結果 <a class="header-anchor" href="#過濾結果" aria-label="Permalink to “過濾結果”">​</a></h3><p>界面的底部菜單欄是專門用於過濾結果的菜單欄。此過濾器不會更改 Wireshark 收集的數據，它只允許你更輕鬆地對其進行排序。有一個文本字段用於輸入新的過濾器表達式，並帶有一個下拉箭頭以查看以前輸入的過濾器。旁邊是一個標為 “Expression” 的按鈕，另外還有一些用於清除和保存當前表達式的按鈕。</p><p>點擊 “Expression” 按鈕。你將看到一個小窗口，其中包含多個選項。左邊一欄有大量的條目，每個都有附加的摺疊子列表。你可以用這些來過濾所有不同的協議、字段和信息。你不可能看完所有，所以最好是大概看下。你應該注意到了一些熟悉的選項，如 HTTP、SSL 和 TCP。</p><p><img src="https://linuxconfig.org/images/wireshark-results-filter.jpg" alt="Wireshark dailog for creating a results filter"></p><p>子列表包含可以過濾的不同部分和請求方法。你可以看到通過 GET 和 POST 請求過濾 HTTP 請求。</p><p>你還可以在中間看到運算符列表。通過從每列中選擇條目，你可以使用此窗口創建過濾器，而不用記住 Wireshark 可以過濾的每個條目。對於過濾結果，比較運算符使用一組特定的符號。 <code>==</code> 用於確定是否相等。<code>&gt;</code> 用於確定一件東西是否大於另一個東西，<code>&lt;</code> 找出是否小一些。 <code>&gt;=</code> 和 <code>&lt;=</code> 分別用於大於等於和小於等於。它們可用於確定數據包是否包含正確的值或按大小過濾。使用 <code>==</code> 僅過濾 HTTP GET 請求的示例如下：<code>http.request.method == &quot;GET&quot;</code>。</p><p>布爾運算符基於多個條件將小的表達式串到一起。不像是抓包所使用的單詞，它使用三個基本的符號來做到這一點。<code>&amp;&amp;</code> 代表 “與”。當使用時，<code>&amp;&amp;</code> 兩邊的兩個語句都必須為真值才行，以便 Wireshark 來過濾這些包。<code>||</code> 表示 “或”。只要兩個表達式任何一個為真值，它就會被過濾。如果你正在查找所有的 GET 和 POST 請求，你可以這樣使用 <code>||</code>：<code>(http.request.method == &quot;GET&quot;) || (http.request.method == &quot;POST&quot;)</code>。<code>!</code> 是 “非” 運算符。它會尋找除了指定的東西之外的所有東西。例如，<code>!http</code> 將展示除了 HTTP 請求之外的所有東西。</p><h3 id="總結思考" tabindex="-1">總結思考 <a class="header-anchor" href="#總結思考" aria-label="Permalink to “總結思考”">​</a></h3><p>過濾 Wireshark 可以讓你有效監控網絡流量。熟悉可以使用的選項並習慣你可以創建過濾器的強大表達式需要一些時間。然而一旦你學會了，你將能夠快速收集和查找你要的網絡數據，而無需梳理長長的數據包或進行大量的工作。</p><hr>',23)),o("p",null,[e[1]||(e[1]=r("via: ",-1)),a(t,{href:"https://linuxconfig.org/filtering-packets-in-wireshark-on-kali-linux"},{default:i(()=>[...e[0]||(e[0]=[r("https://linuxconfig.org/filtering-packets-in-wireshark-on-kali-linux",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=r("作者：",-1)),a(t,{href:"https://linuxconfig.org/filtering-packets-in-wireshark-on-kali-linux"},{default:i(()=>[...e[2]||(e[2]=[r("Nick Congleton",-1)])]),_:1}),e[6]||(e[6]=r(" 譯者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:i(()=>[...e[3]||(e[3]=[r("geekpi",-1)])]),_:1}),e[7]||(e[7]=r(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[r("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=r("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[r("LCTT",-1)])]),_:1}),e[11]||(e[11]=r(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[r("Linux中國",-1)])]),_:1}),e[12]||(e[12]=r(" 榮譽推出",-1))])])}const W=n(h,[["render",c]]);export{P as __pageData,W as default};
